"236\" width=\"4\" height=\"30\" fill=\"#a78bfa\" /><circle cx=\"26\" cy=\"251.0\" r=\"10\" fill=\"#a78bfa\" /><text x=\"26\" y=\"254.0\" text-anchor=\"middle\" fill=\"#0b1220\" font-size=\"11\" font-weight=\"700\" font-family=\"Inter,system-ui,sans-serif\">13</text><text x=\"48\" y=\"256.0\" fill=\"#a78bfa\" font-size=\"14\" font-family=\"Inter,system-ui,sans-serif\">👤</text><text x=\"70\" y=\"252\" fill=\"#a78bfa\" font-size=\"11\" font-weight=\"700\" font-family=\"Inter,system-ui,sans-serif\">1931</text><text x=\"70\" y=\"250\" fill=\"#e2e8f0\" font-size=\"9\" font-weight=\"600\" font-family=\"Inter,system-ui,sans-serif\">Finally, in March 1931, the…</text></g><g class=\"el\" data-beat=\"14\"><rect x=\"304\" y=\"236\" width=\"288\" height=\"30\" rx=\"6\" fill=\"rgba(8,15,30,0.82)\" stroke=\"#fb923c\" stroke-width=\"1\" /><rect x=\"304\" y=\"236\" width=\"4\" height=\"30\" fill=\"#fb923c\" /><circle cx=\"322\" cy=\"251.0\" r=\"10\" fill=\"#fb923c\" /><text x=\"322\" y=\"254.0\" text-anchor=\"middle\" fill=\"#0b1220\" font-size=\"11\" font-weight=\"700\" font-family=\"Inter,system-ui,sans-serif\">14</text><text x=\"344\" y=\"256.0\" fill=\"#fb923c\" font-size=\"14\" font-family=\"Inter,system-ui,sans-serif\">👤</text><text x=\"366\" y=\"250\" fill=\"#e2e8f0\" font-size=\"9\" font-weight=\"600\" font-family=\"Inter,system-ui,sans-serif\">my little friend, the Salt…</text></g>"
