"#f472b6\" /><text x=\"460\" y=\"195\" text-anchor=\"middle\" fill=\"#0b1220\" font-size=\"9\" font-weight=\"700\" font-family=\"Inter,system-ui,sans-serif\">10</text><text x=\"472\" y=\"195\" fill=\"#f472b6\" font-size=\"9\" font-weight=\"700\" font-family=\"Inter,system-ui,sans-serif\">1931</text><text x=\"454\" y=\"208\" fill=\"#e2e8f0\" font-size=\"8\" font-family=\"Inter,system-ui,sans-serif\">Let me give you one</text><text x=\"454\" y=\"218\" fill=\"#e2e8f0\" font-size=\"8\" font-family=\"Inter,system-ui,sans-serif\">more…</text></g><g class=\"el\" data-beat=\"11\"><rect x=\"8\" y=\"360\" width=\"584\" height=\"44\" rx=\"6\" fill=\"rgba(34,197,94,0.18)\" stroke=\"#22c55e\" stroke-width=\"1.5\" /><text x=\"20\" y=\"376\" fill=\"#22c55e\" font-size=\"11\" font-weight=\"700\" font-family=\"Inter,system-ui,sans-serif\">✓ SYNTHESIS — THE WINNING FORMULA</text><text x=\"20\" y=\"392\" fill=\"#bbf7d0\" font-size=\"10\" font-family=\"Inter,system-ui,sans-serif\">Poetry + Newspaper + Festival + Image = a NATION awakened in the mind</text></g><g class=\"el\" data-beat=\"12\"><rect x=\"8\" y=\"410\" width=\"584\" height=\"44\" rx=\"6\" fill=\"rgba(251,191,36,0.18)\" stroke=\"#fbbf24\" stroke-width=\"1.5\" /><text x=\"20\" y=\"426\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"700\" font-family=\"Inter,system-ui,sans-serif\">→ CONCLUSION</text><text x=\"20\" y=\"442\" fill=\"#fde68a\" font-size=\"10\" font-family=\"Inter,system-ui,sans-serif\">Freedom was won in the Indian MIND before it was won on the Indian map</text></g>"
